// Package keysym maps xkbcommon keysym names to their values and back.
//
// The table is generated by `make generate` from the system's
// xkbcommon-keysyms.h, so it matches the keysyms river knows about.
package keysym

import (
	"strings"
	"sync"
)

// entry is one #define from xkbcommon-keysyms.h, in header order.
type entry struct {
	name       string
	sym        uint32
	deprecated bool
}

type maps struct {
	byName map[string][]int // lower-cased name to table indexes
	bySym  map[uint32]string
}

var lookup = sync.OnceValue(func() maps {
	m := maps{byName: map[string][]int{}, bySym: map[uint32]string{}}
	for i, e := range table {
		lower := strings.ToLower(e.name)
		m.byName[lower] = append(m.byName[lower], i)
	}
	// A keysym's name is the first one that parses back to it, preferring
	// names that aren't deprecated aliases.
	for _, deprecated := range []bool{false, true} {
		for _, e := range table {
			if _, ok := m.bySym[e.sym]; ok || e.deprecated != deprecated {
				continue
			}
			if sym, _ := m.fromName(e.name); sym == e.sym {
				m.bySym[e.sym] = e.name
			}
		}
	}
	return m
})

// FromName returns the keysym with the given name, ignoring case as
// xkbcommon does: of names differing only in case, the lower-case one wins.
func FromName(name string) (uint32, bool) {
	return lookup().fromName(name)
}

func (m maps) fromName(name string) (uint32, bool) {
	lower := strings.ToLower(name)
	idx := m.byName[lower]
	if len(idx) == 0 {
		return 0, false
	}
	best := idx[0]
	for _, i := range idx {
		if table[i].name == lower {
			return table[i].sym, true
		}
		if table[best].deprecated && !table[i].deprecated {
			best = i
		}
	}
	return table[best].sym, true
}

// Name returns the name the config generator writes for a keysym: the first
// name xkbcommon-keysyms.h defines for it that parses back to it. Keysyms no
// name leads to, such as upper-case letters, have none.
func Name(sym uint32) (string, bool) {
	name, ok := lookup().bySym[sym]
	return name, ok
}
